/**
 * Stable native-facing failures. Variants and messages contain no health or fixture values.
 */
sealed class HealthmdCoreException: kotlin.Exception() {
    
    /**
     * The expected digest was malformed.
     */
    class InvalidFixtureDigest(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The fixture exceeded the public boundary limit.
     */
    class FixtureTooLarge(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The exact bytes did not match the expected digest.
     */
    class FixtureDigestMismatch(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The fixture envelope was invalid.
     */
    class InvalidFixture(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The JSON bytes were not canonical.
     */
    class NonCanonicalFixture(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The fixture envelope version was unsupported.
     */
    class UnsupportedFixtureFormatVersion(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The semantic input version was unsupported.
     */
    class UnsupportedSemanticInputVersion(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The registry version was unsupported.
     */
    class UnsupportedRegistryVersion(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The persisted-state version was unsupported.
     */
    class UnsupportedPersistedStateVersion(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The embedded registry failed deterministic validation.
     */
    class InvalidRegistry(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The requested registry profile was unsupported.
     */
    class UnsupportedRegistryProfile(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Semantic configuration exceeded its bounded input limit.
     */
    class SemanticConfigTooLarge(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Semantic configuration was invalid.
     */
    class InvalidSemanticConfig(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * One semantic batch exceeded its bounded input limit.
     */
    class SemanticBatchTooLarge(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * One semantic batch was invalid.
     */
    class InvalidSemanticBatch(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A bounded semantic session limit was exceeded.
     */
    class SemanticLimitExceeded(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Semantic batch or record ordering was invalid.
     */
    class SemanticSequenceInvalid(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The semantic session had already completed or observed cancellation.
     */
    class SemanticSessionTerminal(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * The explicit profile does not support the requested semantic operation.
     */
    class UnsupportedSemanticOperation(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    
    /**
     * A Rust panic was contained at the native boundary.
     */
    class InternalPanic(
        ) : HealthmdCoreException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<HealthmdCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): HealthmdCoreException = FfiConverterTypeHealthmdCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeHealthmdCoreError : FfiConverterRustBuffer<HealthmdCoreException> {
    override fun read(buf: ByteBuffer): HealthmdCoreException {
        

        return when(buf.getInt()) {
            1 -> HealthmdCoreException.InvalidFixtureDigest()
            2 -> HealthmdCoreException.FixtureTooLarge()
            3 -> HealthmdCoreException.FixtureDigestMismatch()
            4 -> HealthmdCoreException.InvalidFixture()
            5 -> HealthmdCoreException.NonCanonicalFixture()
            6 -> HealthmdCoreException.UnsupportedFixtureFormatVersion()
            7 -> HealthmdCoreException.UnsupportedSemanticInputVersion()
            8 -> HealthmdCoreException.UnsupportedRegistryVersion()
            9 -> HealthmdCoreException.UnsupportedPersistedStateVersion()
            10 -> HealthmdCoreException.InvalidRegistry()
            11 -> HealthmdCoreException.UnsupportedRegistryProfile()
            12 -> HealthmdCoreException.SemanticConfigTooLarge()
            13 -> HealthmdCoreException.InvalidSemanticConfig()
            14 -> HealthmdCoreException.SemanticBatchTooLarge()
            15 -> HealthmdCoreException.InvalidSemanticBatch()
            16 -> HealthmdCoreException.SemanticLimitExceeded()
            17 -> HealthmdCoreException.SemanticSequenceInvalid()
            18 -> HealthmdCoreException.SemanticSessionTerminal()
            19 -> HealthmdCoreException.UnsupportedSemanticOperation()
            20 -> HealthmdCoreException.InternalPanic()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

